const raw = $input.item.json || {};
const extracted = raw.extracted_params || {};
const rawText = (raw.rawText || raw.userPrompt || raw.text || '').toString().trim();
const rawCommand = (raw.downstream_command || raw.intent || 'ADMIN_STATUS').toString().toUpperCase().trim();

let command = rawCommand === 'CHANGE_CHARACTER_VOICE' ? 'CHANGE_VOICE' : rawCommand;

const isConfirmYes = /^(#?\s*(haan|yes|confirm|proceed|kar\s*do))\b/i.test(rawText);
const isConfirmCancel = /^(#?\s*(cancel|nahi|no|abort|ruk\s*jao))\b/i.test(rawText);

if (/^#?\s*llm_usage\b/i.test(rawText)) command = 'LLM_USAGE';
else if (/^#?\s*project_list\b/i.test(rawText)) command = 'PROJECT_LIST';
else if (/^#?\s*episode_list\b/i.test(rawText)) command = 'EPISODE_LIST';
else if (/^#?\s*(project_switch|open_project)\b/i.test(rawText)) command = 'PROJECT_SWITCH';
else if (/^#?\s*project_delete\b/i.test(rawText)) command = 'PROJECT_DELETE';
else if (/^#?\s*view_manual_review/i.test(rawText)) command = 'VIEW_MANUAL_REVIEW_QUEUE';
else if (/^#?\s*retry_vision/i.test(rawText)) command = 'RETRY_VISION_ANALYSIS';

const project_id = raw.project_id || extracted.project_id || null;
const episode_no = Number(raw.episode_no || raw.episode_number || extracted.episode_number || 1);
const sessionId = (raw.sessionId || `sess_${$execution.id}`).toString();

let top_branch = 'DIRECT_SAFE';

if (['PROJECT_DELETE', 'ADMIN_STOP_KAGGLE'].includes(command) || isConfirmYes || isConfirmCancel) {
  top_branch = 'DESTRUCTIVE_GATE';
} else if (['CHANGE_VOICE', 'PREVIEW_VOICE', 'LIST_VOICES', 'RESET_VOICE'].includes(command)) {
  top_branch = 'VOICE_R12';
} else if (['VIEW_MANUAL_REVIEW_QUEUE', 'RETRY_VISION_ANALYSIS', 'RETRY_FAILED'].includes(command)) {
  top_branch = 'MANUAL_REVIEW_PART_Q';
} else if (command === 'PUBLISH_NOW') {
  top_branch = 'PUBLISH_GATE_WF07';
} else if (['PROJECT_CREATE', 'PROJECT_UPDATE', 'CHARACTER_ADD', 'CHARACTER_EDIT', 'RULE_ADD', 'UPDATE_ARC', 'UPDATE_POWER', 'UPDATE_RELATIONSHIP', 'UPDATE_KNOWLEDGE', 'UPDATE_LOCATION', 'UPDATE_ARTIFACT', 'UPDATE_MYSTERY', 'UPDATE_FORESHADOW', 'ADD_TIMELINE_EVENT'].includes(command)) {
  top_branch = 'AI_ASSISTED_MUTATION';
}

return { json: { ...raw, command, top_branch, rawText, project_id, episode_no, sessionId, is_confirm_yes: isConfirmYes, is_confirm_cancel: isConfirmCancel, extracted_params: extracted, timestamp: $now.toISOString() } };

const gw = $('Command Gateway & Router').first().json;
const resp = $input.item.json;
const rows = Array.isArray(resp) ? resp : (resp && resp.id ? [resp] : []);

let msg = '';
if (gw.command === 'ADMIN_START_KAGGLE') {
  msg = `🚀 **WF-04: Kaggle Session Started!**\n• Session \`kaggle_story_engine\` boot signal sent successfully.`;
} else if (gw.command === 'PROJECT_SWITCH') {
  msg = `🔄 **WF-04: Project Switched!**\n• Project \`${gw.project_id}\` is now set to \`is_active = true\`.`;
} else if (gw.command === 'PROJECT_LIST') {
  const listStr = rows.map(r => `• ${r.name} (\`${r.id}\`) — Active: ${r.is_active}`).join('\n') || '• Active project loaded.';
  msg = `📁 **WF-04: Registered Projects:**\n${listStr}`;
} else {
  msg = `🟢 **WF-04: ${gw.command} — System Online!**\n• Supabase PostgREST: Healthy | Active Project ID: \`${gw.project_id}\``;
}

return { json: { ...gw, branch_status: 'DIRECT_COMMAND_COMPLETED', formatted_output: msg } };

const gw = $('Command Gateway & Router').first().json;
const rawLock = $input.item.json;
const pendingRow = Array.isArray(rawLock) ? rawLock[0] : (rawLock && rawLock.id ? rawLock : null);

const nowMs = Date.now();
let isLockValid = false;
let lockedAction = null;

if (pendingRow && pendingRow.expires_at) {
  const expiresMs = new Date(pendingRow.expires_at).getTime();
  if (expiresMs > nowMs) {
    isLockValid = true;
    lockedAction = pendingRow.action_type;
  }
} else if (pendingRow && pendingRow.created_at) {
  const createdMs = new Date(pendingRow.created_at).getTime();
  const ageMinutes = (nowMs - createdMs) / 60000;
  if (ageMinutes <= 10) {
    isLockValid = true;
    lockedAction = pendingRow.action_type;
  }
}

if (gw.is_confirm_cancel) {
  return { json: { ...gw, destructive_decision: 'CANCELLED', pending_id: pendingRow?.id || null, formatted_output: `🛡️ **Destructive Action Cancelled!** Koi bhi project delete ya Kaggle session stop nahi kiya gaya.` } };
}

if (gw.is_confirm_yes && isLockValid && ['PROJECT_DELETE', 'ADMIN_STOP_KAGGLE'].includes(lockedAction)) {
  return { json: { ...gw, command: lockedAction, destructive_decision: lockedAction === 'ADMIN_STOP_KAGGLE' ? 'EXECUTE_STOP_KAGGLE' : 'EXECUTE_DELETE_PROJECT', pending_id: pendingRow.id, formatted_output: `✅ **Confirmed (${lockedAction})!** Executing destructive operation now.` } };
}

const targetAction = ['PROJECT_DELETE', 'ADMIN_STOP_KAGGLE'].includes(gw.command) ? gw.command : 'ADMIN_STOP_KAGGLE';
const expiresIso = new Date(nowMs + 10 * 60000).toISOString();

return {
  json: {
    ...gw,
    destructive_decision: 'PROMPT_CONFIRMATION',
    confirmation_insert_payload: {
      project_id: gw.project_id,
      action_type: targetAction,
      status: 'AWAITING_CONFIRMATION',
      action_payload: { requested_by: gw.sessionId },
      expires_at: expiresIso
    },
    formatted_output: `⚠️ **CRITICAL SAFETY GATE (${targetAction}):**\nKya aap sach me \`${targetAction}\` execute karna chahte hain?\n• Ye confirmation **10 minutes** (\`${expiresIso}\`) me expire ho jayegi.\n• Proceed karne ke liye **"haan"** reply karein, ya rokne ke liye **"cancel"** likhein.`
  }
};

const gw = $('Command Gateway & Router').first().json;
const voicesRaw = $('Supabase: Fetch Active Voice Catalog').all().map(i => i.json);
const charsRaw = $input.all().map(i => i.json);
const voices = Array.isArray(voicesRaw[0]) ? voicesRaw[0] : voicesRaw.filter(v => v && v.voice_id);
const chars = Array.isArray(charsRaw[0]) ? charsRaw[0] : charsRaw.filter(c => c && c.character_code);

if (gw.command === 'LIST_VOICES') {
  const listText = voices.map(v => `• \`${v.voice_id}\` (${v.voice_name}) — ${v.provider} | ${v.gender} | ${v.language}`).join('\n') || '• Default Svara/Supertonic voices active.';
  return { json: { ...gw, needs_voice_mutation: false, formatted_output: `🎙️ **WF-04: Active Voice Catalog (Rule 40):**\n${listText}` } };
}

const targetCharCode = (gw.extracted_params?.character_name || gw.extracted_params?.character_code || 'CHAR_001').toString().toUpperCase().trim();
const matchedChar = chars.find(c => (c.character_code || '').toUpperCase() === targetCharCode || (c.name || '').toUpperCase().includes(targetCharCode)) || chars[0] || { character_code: 'CHAR_001', name: 'Protagonist', voice_config: {} };
const existingVc = (matchedChar.voice_config && typeof matchedChar.voice_config === 'object') ? matchedChar.voice_config : {};

if (gw.command === 'PREVIEW_VOICE') {
  const previewVoiceId = gw.extracted_params?.voice_id || existingVc.voice_id || 'svara_hi_male_hero_01';
  return { json: { ...gw, needs_voice_mutation: false, formatted_output: `🎧 **WF-04: Voice Preview Generated!**\n• Character: \`${matchedChar.character_code}\` | Voice ID: \`${previewVoiceId}\`\n• Preview URL: \`${$env.SUPABASE_URL}/storage/v1/object/public/previews/${previewVoiceId}_sample.wav\`` } };
}

const currentVer = Number(existingVc.version || 1);
const nextVer = currentVer + 1;
const newVoiceId = gw.command === 'RESET_VOICE' ? 'svara_hi_male_hero_01' : (gw.extracted_params?.voice_id || 'svara_hi_male_hero_01');
const matchedCatalogVoice = voices.find(v => v.voice_id === newVoiceId) || { provider: 'Svara TTS', gender: existingVc.gender || 'male', language: 'hi' };

const versionedVoiceConfig = {
  voice_id: newVoiceId,
  voice_provider: matchedCatalogVoice.provider || 'Svara TTS',
  voice_model: existingVc.voice_model || 'svara-v2-hi',
  language: matchedCatalogVoice.language || 'hi',
  gender: matchedCatalogVoice.gender || 'male',
  pitch: 1.0,
  speed: 1.0,
  version: nextVer,
  status: 'pending_approval',
  emotion_profile: { neutral: { pitch: 1.00, rate: 1.00 }, anger: { pitch: 0.95, rate: 1.10 }, joy: { pitch: 1.05, rate: 1.05 }, sadness: { pitch: 0.90, rate: 0.90 }, fear: { pitch: 1.02, rate: 1.08 } },
  previous_voice_id: existingVc.voice_id || null,
  changed_at: $now.toISOString(),
  changed_by: gw.sessionId
};

return {
  json: {
    ...gw,
    needs_voice_mutation: true,
    target_character_code: matchedChar.character_code,
    versioned_voice_config: versionedVoiceConfig,
    pending_voice_approval: {
      project_id: gw.project_id,
      action_type: gw.command,
      entity_type: 'CHARACTER_VOICE',
      entity_code: matchedChar.character_code,
      status: 'PENDING',
      action_payload: { previous_version: currentVer, new_version: nextVer, new_voice_config: versionedVoiceConfig }
    },
    formatted_output: `🎙️ **WF-04: R12 Versioned Voice Updated (${gw.command})!**\n• **Character:** \`${matchedChar.character_code}\` (${matchedChar.name})\n• **New Voice ID:** \`${newVoiceId}\` | **Version:** \`v${currentVer} -> v${nextVer}\`\n• **Approval State:** Logged in \`pending_actions\` (\`pending_approval\`).`
  }
};

