const WHITELIST = new Set(['projects', 'characters', 'story_rules', 'character_arcs', 'power_system', 'character_relationships', 'locations', 'artifacts', 'mystery_tracker', 'story_timeline']);
let parsed = null;
try {
  const content = llmRaw?.choices?.[0]?.message?.content;
  if (content) parsed = JSON.parse(content.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim());
} catch (e) { parsed = null; }

const table = (parsed && WHITELIST.has(parsed.target_table)) ? parsed.target_table : 'story_rules';
const rec = (parsed && parsed.record && typeof parsed.record === 'object') ? parsed.record : { rule_code: 'RULE_ADMIN', rule_text: gw.rawText };
if (table !== 'projects') rec.project_id = gw.project_id;

return { json: { ...gw, target_table: table, mutation_record: rec, formatted_output: `✨ **WF-04: AI Admin Mutation (${gw.command})**\n• Target Table: \`${table}\`\n• Summary: ${parsed?.summary || 'Record updated successfully.'}` } };

